\label{thm:main}
For every $0<s<1/2$, there exists an $s$-Ahlfors regular compact set
$K\subset\mathbb{R} \subset {\mathbb C}$ such that, if $\omega^\infty$ denotes the harmonic
measure of ${\mathbb C} \setminus K$ with pole at infinity, 
\[
    \dim_{\mathcal H}\omega^\infty=s.
\]
Moreover, $\omega^\infty$ and $\mathcal{H}^s|_K$ are equivalent, i.e., there is some constant $C \ge 1$ for which 
\begin{align*}
	C^{-1} \, \mathcal{H}^s|_K(F)\le \omega^\infty(F) \le C \mathcal{H}^s|_K(F) \text{ for all } F \subset K \text{ Borel.}
\end{align*}

\label{lem:cheb}
For $1\le j\le N$,
\begin{equation}\label{eqTX20}
 b_j=\log N-(N-1)\log2-\log\sin\theta_j,
 \qquad \beta_j=\log\frac{\sin\theta_1}{\sin\theta_j}\le0.
\end{equation}
Moreover,
\begin{equation}\label{eqTX21}
 \sum_{k\ne j}\frac1{q_j-q_k}=\frac{q_j}{2(1-q_j^2)},
\end{equation}
\begin{equation}\label{eqTX22}
 \sum_{k\ne j}\frac1{|q_j-q_k|^2}\lesssim\frac{N^2}{\sin^2\theta_j},
\end{equation}
and
\begin{equation}\label{eqTX23}
 d_N:=\min_{j\ne k}|q_j-q_k|\simeq N^{-2}, \qquad  \left \lvert { q_j - q_{j+1}  }  \right \rvert    \gtrsim \sin(\theta_j)/ N \simeq \sin(\theta_{j+1})/N.
\end{equation}
The implicit constants are absolute.

\label{lem:ahlf_reg}
	Let $ 0 < s < 1/2$, let $N \in {\mathbb N}$, $Nr^s = 1$, set $K_0 = \{0\}$ and define $K_n$ inductively for $n \ge 1$ by 
	\begin{align*}
		K_n = \bigcup_{p \in K_{n-1}} \{   p + a_{n-1}(p) r^{n-1} Q_p(q_j) \; : \; 1 \le j \le N \},
	\end{align*}
	where $a_0(0)=1$ and $1 \le a_{n-1}(p) \le C_1 N \sin(\theta_{j(p)})$ in the case $n\geq2$, and each $Q_p:[-1,1] \rightarrow [-2,2]$ satisfies
	\begin{align*}
		 \left \lvert {q_j - q_k}  \right \rvert    /2 \le  \left \lvert {  Q_p(q_j) - Q_p(q_k)  }  \right \rvert    \le 2  \left \lvert { q_j -q_k  }  \right \rvert   , \; \; 1 \le j,k \le N.
	\end{align*}
	Then as long as $N$ is large enough depending on $C_1$ and $s$, then for each $x \in K_n$ and $1 \le \ell \le n$,
	\begin{align}\label{eqn:nca}
		\# \mathcal{Y}_\ell(x) = (N-1)N^{\ell-1}, \qquad  N^{-2} r^{n-\ell}  \lesssim  \left \lvert {x-y}  \right \rvert    \lesssim C_1 N r^{n-\ell} \text{ for all } y \in \mathcal{Y}_\ell(x).
	\end{align}
	Consequently, $K_n \rightarrow K$ in the Hausdorff distance, where $K$ is a compact, $s$-Ahlfors regular set, and 
	\begin{align*}
		\mu_n \coloneqq N^{-n} \sum_{x \in K_n} \delta_{x} \rightharpoonup \mu,
	\end{align*}
	where $\mu$ is an $s$-Ahlfors regular measure supported on $K$.

For $\ell \ge 1$, recall the notation $\mathcal Y_\ell(p)$, which denotes the set of points
$y\in K_{n-1}$ whose nearest common ancestor with $p$ is $\ell$ generations above $p$. We split 
\begin{align*}
	\Delta_2 & = N \sum_{y \in K_{n-1} \setminus\{p\}} \left( \log \left \lvert {x-y}  \right \rvert    - \log \left \lvert {p-y}  \right \rvert   \right) =  \sum_{ \ell = 1  }^{n-1} \Delta_2^{(\ell)}, \\
	\Delta_2^{(\ell)} & \coloneqq N \sum_{  y \in \mathcal{Y}_\ell(p) } \left( \log \left \lvert {x-y}  \right \rvert    - \log \left \lvert {p-y}  \right \rvert   \right).
\end{align*}
Recall from Lemma \ref{lem:ahlf_reg} that
\begin{equation}\label{eq:corona-cardinality-delta2}
	\#\mathcal Y_\ell(p)
	=
	(N-1)N^{\ell-1}.
\end{equation}
Let us first estimate $\Delta_2^{(1)}$, which corresponds to the siblings of $p$ in $K_{n-1}$. 

Suppose that \(p\) has index $j$ and parent \(q\in K_{n-2}\), and recall that \(x\in K_n\) has index $k$ and parent \(p\), so that we may write
\begin{align*}
p =q+a_{n-2}(q)r^{n-2}q_j,  \qquad  x=p+a_{n-1}(p)r^{n-1}q_k.
\end{align*}
The elements of $\mathcal{Y}_1(p)$ are given by $y_\ell = q + a_{n-2}(q)r^{n-2} q_\ell$ for $\ell \ne j$, and so direct computation gives us 
\begin{align*}
	\frac{  \left \lvert {x-y_\ell}  \right \rvert    }{ \left \lvert {p - y_\ell}  \right \rvert   } =  \left \lvert { 1 + r \frac{a_{n-1}(p)}{a_{n-2}(q)}  \frac{ q_k  }{q_j - q_\ell}  }  \right \rvert    \eqqcolon  \left \lvert { 1 +  \frac{ t_x  }{q_j - q_\ell}  }  \right \rvert   .
\end{align*}
Since $a_{n-2}(q)\ge1$, $|q_k|\le1$, and $a_{n-1}(p)\lesssim_\eta N\sin\theta_j$, we see
\begin{equation}\label{eq:t-estimate} |t_x| \lesssim_\eta rN\sin\theta_j,
\end{equation} 
and so with the estimate \eqref{eqTX23} we further obtain
\begin{align*}
	 \left \lvert {\frac{t_x}{q_j - q_\ell}  }  \right \rvert    \lesssim_\eta r N^3 \sin\theta_j \ll 1,
\end{align*}
provided that $N$ is sufficiently large. We may then use $\log \left \lvert {1 + u}  \right \rvert    = u + O(u^2)$ for $ \left \lvert {u}  \right \rvert    \le 1/2$ to obtain 
\begin{align*}\label{eq:Delta2-first-exact} \Delta_2^{(1)} =  N\sum_{y \in \mathcal{Y}_1(p)}
	\log\frac{|x-y|}{|p-y|} & = N\sum_{\ell\ne j} \log\left| 1+\frac{t_x}{q_j-q_\ell} \right|  \\
	& = Nt_x\sum_{\ell\ne j}\frac1{q_j-q_\ell} 
	+ O\left( Nt_x^2 \sum_{\ell\ne j} \frac1{|q_j-q_\ell|^2} \right).
\end{align*} 
By applying Lemma \ref{lem:cheb}, \eqref{eq:t-estimate}, and recalling that $(1 - q_j^2) = \sin^2 \theta_j$,  we deduce that 
\begin{equation}\label{eq:Delta2-first-final}
	\begin{split}
	 \left \lvert {  \Delta_2^{(1)}  }  \right \rvert    & \le N  \left \lvert {t_x}  \right \rvert     \left \lvert {\frac{q_j}{2(1- q_j^2)}}  \right \rvert    + C N^3  \left \lvert {t_x}  \right \rvert   ^2/(\sin \theta_j)^2 \\
	& \lesssim_\eta r N^2/(\sin \theta_j) + r^2 N^5 \lesssim N^3r+N^5r^2,
	\end{split}
\end{equation}
since $\sin\theta_j \ge \sin \theta_1 \simeq N^{-1}$.

We now estimate the contribution of the $\mathcal{Y}_\ell(p)$ for $\ell \ge 2$, which is much simpler. Fix $y \in \mathcal{Y}_\ell(p)$, and recall from Lemma \ref{lem:ahlf_reg} that for $N$ large enough, we have 
\begin{align*}
	 \left \lvert {p-y}  \right \rvert    \gtrsim N^{-2} r^{n-\ell-1},
\end{align*}
while we have for $h = x-p$ that $ \left \lvert {h}  \right \rvert    \lesssim_\eta N r^{n-1}$. Hence we may again expand $\log \left \lvert {1+ u}  \right \rvert    \simeq u$ for $u$ small to see 
\begin{align*}
	 \left \lvert {\log \frac{ \left \lvert {x-y}  \right \rvert   }{ \left \lvert {p-y}  \right \rvert   }}  \right \rvert    =  \left \lvert {\log  \left \lvert {  1 + \frac{h}{p-y}  }  \right \rvert   }  \right \rvert    \lesssim_\eta   N^3r^\ell, 
\end{align*}
where the expansion is justified since $\ell \ge 2$ and $N^3 r^2 \ll 1$ for $N$ large. Altogether, we estimate using the above inequality along with \eqref{eq:corona-cardinality-delta2},
\begin{align*}
	 \left \lvert { \sum_{\ell = 2}^{n-1} \Delta_2^{\ell} }  \right \rvert    \le N \sum_{\ell=2}^{n-1} \sum_{y \in \mathcal{Y}_\ell(p)}  \left \lvert { \log \frac{ \left \lvert {x-y}  \right \rvert   }{ \left \lvert {p-y}  \right \rvert   }  }  \right \rvert    \lesssim_\eta  N \sum_{\ell=2}^{n-1} N^3 r^\ell N^\ell \lesssim N^6 r^2 \ll 1,
\end{align*}
since $Nr \ll 1$ for $N$ large. Along with \eqref{eq:Delta2-first-final} this completes the proof of the estimate on $\Delta_2$. 



\vspace{1em} 


Now, we move to the estimates for $\Delta_3$. Recall that
\[
\Delta_3
=
\sum_{\substack{y\in K_{n-1}\\ y\ne p}}
\sum_{\widehat z=y}
\bigl(
\log|x-z|-\log|x-y|
\bigr).
\]
For $y\in K_{n-1}\setminus\{p\}$, the $N$ children of $y$ are
\[
z_m
=
y+a_{n-1}(y)r^{n-1}q_m,
\qquad 1\le m\le N,
\]
and so the contribution of the children of $y$ to $\Delta_3$ can be
written as
\begin{align}
\sum_{\widehat z=y}
\bigl(
\log|x-z|-\log|x-y|
\bigr)
&=
\sum_{m=1}^N
\log\left|
1-\frac{a_{n-1}(y)r^{n-1}q_m}{x-y}
\right|.
\label{eq:Delta3-one-parent}
\end{align}
We claim that $a_{n-1}(y) r^{n-1}q_m / (x-y)$ is sufficiently small, so that we can use the expansion $\log \left \lvert {1 + u}  \right \rvert    = u + O(u^2)$ in each logarithm above.

Indeed, if $y \in \mathcal{Y}_\ell(p)$ for some $1 \le \ell \le n-1$, then we may apply Lemma \ref{lem:ahlf_reg} to see that 
\begin{align}\label{eqn:x-y_low}
	 \left \lvert {x-y}  \right \rvert    \ge  \left \lvert {y-p}  \right \rvert    -  \left \lvert {x-p}  \right \rvert    \gtrsim_\eta N^{-2} r^{n-1-\ell} - a_{n-1}(p) r^{n-1} \ge r^{n-1-\ell} \left(  N^{-2} - C_\eta N r^\ell \right).
\end{align}
Since $s < 1/3$ and $r = N^{-1/s}$, then as long as $N$ is chosen large enough, the difference in the last line can be made positive, and we have that $ \left \lvert {x-y}  \right \rvert    \gtrsim_\eta r^{n-1-\ell} N^{-2}$. On the other hand, we have that $ \left \lvert {a_{n-1}(y) r^{n-1} q_m}  \right \rvert    \lesssim_\eta N r^{n-1}$, and so 
\begin{align*}
	 \left \lvert { \frac{a_{n-1}(y) r^{n-1} q_m}{x-y}  }  \right \rvert    \lesssim_\eta N^3 r^\ell \le N^3 r \ll 1, 
\end{align*}
again since $0 < s < 1/3$. Expanding the logarithm in \eqref{eq:Delta3-one-parent} and using the identity $\sum_{m=1}^Nq_m=0$ to cancel the linear term in $q_m$, we see that 
\begin{align}
	\left|
	\sum_{\widehat z=y}
	\bigl(
	\log|x-z|-\log|x-y|
	\bigr)
	\right|
	&\lesssim
	\sum_{m=1}^N
	\frac{a_{n-1}(y)^2r^{2n-2}q_m^2}{|x-y|^2}
	\lesssim
	N\frac{a_{n-1}(y)^2r^{2n-2}}{|x-y|^2}.
	\label{eq:Delta3-one-parent-bound}
\end{align}
As in the estimates for $\Delta_2$, we split our estimates by generations $\mathcal{Y}_\ell(p)$ for $\ell =1$ and $2 \le \ell \le n-1$; that is, we write 
\begin{align*}
	\Delta_3 = \sum_{\ell=1}^{n-1} \Delta_3^{(\ell)}, \qquad \Delta_3^{(\ell)} = \sum_{y \in \mathcal{Y}_\ell(p)} \sum_{\hat{z} = y} \left(  \log  \left \lvert {x-z}  \right \rvert    -\log  \left \lvert {x-y}  \right \rvert     \right).
\end{align*}

For $\ell =1$, suppose that $p$ has index $j$ and parent $q \in K_{n-2}$, so that $p = q + a_{n-2}(q) r^{n-2} q_j$. The other
children of $q$ (i.e., the elements of $\mathcal{Y}_1(p)$) are $y_i
=
q+a_{n-2}(q)r^{n-2}q_i$ for $i\ne j$. 
Since
\[
p-y_i
=
a_{n-2}(q)r^{n-2}(q_j-q_i), \text{  and  } 
x-p=O_\eta(Nr^{n-1}),
\]
the smallness assumption $N^3r\ll_\eta1$ implies
\[
|x-y_i|\approx |p-y_i|
\approx
a_{n-2}(q)r^{n-2}|q_j-q_i|,
\]
with constants independent of $N$. 
Therefore, using
$a_{n-2}(q)\ge1$, \eqref{eq:Delta3-one-parent-bound} yields
\begin{align}
	|\Delta_3^{(1)}|
	&\lesssim
	N
	\sum_{i \ne j}
	\frac{a_{n-1}(y_i)^2r^{2n-2}}
	{a_{n-2}(q)^2r^{2n-4}|q_j-q_i|^2}
	\lesssim
	Nr^2
	\sum_{i \ne j}
	\frac{a_{n-1}(y_i)^2}{|q_j-q_i|^2}.
	\label{eq:Delta3-first-pre}
\end{align}
Since $y_i$ has index $i$, we have the bound $a_{n-1}(y_i)
\lesssim_\eta
N\sin\theta_i$ and thus 
\begin{align}
	\sum_{i\ne j}
	\frac{a_{n-1}(y_i)^2}{|q_j-q_i|^2}
	&\lesssim_\eta
	N^2
	\sum_{i\ne j}
	\frac{\sin^2\theta_i}{|q_j-q_i|^2} \lesssim_\eta N^4,
\end{align}
where the last inequality follows from Lemma~\ref{lem:weighted}, with $m=a=2$. Substituting into \eqref{eq:Delta3-first-pre}, we obtain
\begin{equation}\label{eq:Delta3-first-final}
	|\Delta_3^{(1)}|
	\lesssim_\eta
	N^5r^2.
\end{equation}

The estimates for $\Delta_3^{(\ell)}$ with $\ell \ge 2$, as in the case of $\Delta_2$, are much simpler. We use the previous bound $ \left \lvert {x-y}  \right \rvert    \gtrsim_\eta N^{-2} r^{n-1-\ell}$ from \eqref{eqn:x-y_low}, the fact that $\# \mathcal{Y}_\ell(p) = (N-1)N^{\ell-1} \le N^\ell$, and the crude upper bound $ \left \lvert {a_{n-1}(y)}  \right \rvert    \lesssim_\eta N$ to pass from \eqref{eq:Delta3-one-parent-bound} to
\begin{align*}
	\sum_{\ell = 2}^{n-1} |\Delta_3^{(\ell)}| \lesssim \sum_{\ell=2}^{n-1} \sum_{y \in \mathcal{Y}_\ell (p)} N \frac{  a_{n-1}(y)^2 r^{2n-2}  }{ \left \lvert {x-y}  \right \rvert   ^2} \lesssim N^7 \sum_{\ell=2}^{n-1} (N r^2)^{\ell } \lesssim N^9 r^4,
\end{align*}
where again the summability of the geometric series comes from the fact that $N r^2 \ll 1$. Combining the above with \eqref{eq:Delta3-first-final}, we conclude 
\begin{align*}
	 \left \lvert {\Delta_3}  \right \rvert    \lesssim N^5 r^2 + N^9 r^4
\end{align*}
as desired.

