\label{thm:one-third}
	For every $0 < s< 1/3$, there exists an $s$-Ahlfors regular compact set $K \subset {\mathbb R} \subset {\mathbb C}$ so that the harmonic measure in ${\mathbb C} \setminus K$ with pole at infinity $\omega^\infty$ is equivalent to $\mathcal{H}^s|_K$, i.e., for some constant $C \ge 1$, 
	\begin{align*}
		C^{-1} \, \mathcal{H}^s|_K(F)\le \omega^\infty(F) \le C \mathcal{H}^s|_K(F) \text{ for all } F \subset K \text{ Borel.}
	\end{align*}
	In particular, $\dim \omega^\infty = s$.

Since the proof of this Theorem follows from the arguments in \cite{DJJ23}, we outline just the steps. As long as $N$ is chosen large enough, Lemma \ref{lem:ahlf_reg} shows that $K_n$ converge in the Hausdorff metric to a compact, $s$-Ahlfors regular subset $K \subset {\mathbb R}\subset {\mathbb C}$. Moreover, if $\mu$ is the weak limit of the Radon measures
	\begin{align*}
		\mu_n = N^{-n} \sum_{x \in K_n} \delta_x, 
	\end{align*}
	then we know that $\mu$ is an $s$-Ahlfors regular probability measure supported on $K$, and thus is equivalent to $\mathcal{H}^s|_K$. Arguing just as in \cite[Lemma 3.3]{DJJ23}, but now using Lemma \ref{lem:basic-ind}, one can show that the potential
	\begin{align*}
		g_\mu(x) = \int \log  \left \lvert { x-y}  \right \rvert     d\mu(y) 
	\end{align*}
	is constant on $K$, and so by uniqueness, $\mu$ is the equilibrium measure for $K$. Since $K$ is $s$-Ahlfors regular with $s > 0$, we know that ${\mathbb C} \setminus K$ is Wiener regular, and so the equilibrium measure $\mu = \omega_{{\mathbb C}\setminus K}^\infty$ is exactly the harmonic measure with pole at infinity. Since $\mu$ is equivalent to $\mathcal{H}^s|_K$, this completes the proof.

\label{lem:L_prop}
	Let $ M \in {\mathbb N}$ and let $N \ge 2M+1$. For each $0 \le m \le M$, the operator 
	\begin{align*}
		L: \mathcal{P}_{m+1}/{\mathbb R} \rightarrow \mathcal{P}_m 
	\end{align*}
	is an isomorphism for which $\deg( LP) \le \deg(P) - 1$, and for which the inverse $L(P) = L(P + \mathrm{const}) = R$ for $R \in \mathcal{P}_m$ satisfies
	\begin{align*}
		\| P - N^{-1}\sum_{k=1}^N P(q_k)  \|_{C^1([-1,1])} \le \frac{C_M}{N} \| R \|_{\mathrm{coeff}}.
	\end{align*}

\label{lem:prev_estimates}
	Suppose $K_m$ has been constructed for $0 \le m \le n-1$ as above, i.e., so that the children of $K_{m-1}$ all satisfy \eqref{eq:old-children}, \eqref{eq:Q-close-id}, and \eqref{eq:Q-barycenter}, and so that the $a_{m}(z)$ satisfy \eqref{eq:old-scale-bound}. 

	Then as long as $N$ is sufficiently large, depending just on $s$, $M$, and $\eta$, we have that for all $p \ne y$, $p, y\in K_{n-1}$, 
	\begin{equation}
		\label{eq:relative-scale}
		\frac{\rho_p+\rho_y}{|p-y|}
		\lesssim_{M,\eta}\tau,
	\end{equation}
	and moreover, for every
	integer $d\ge2$ and $0\le a\le d$,
	\begin{equation}
		\label{eq:geometric-sum}
		\sum_{\substack{y\in K_{n-1}\\y\neq p}}
		\frac{\rho_p^{\,d-a}\rho_y^{\,a}}
		{|p-y|^d}
		\lesssim_{d,M,\eta}
		\tau^d.
	\end{equation}

We start with the proof of \eqref{eq:relative-scale}. If $p, y \in K_{n-1}$ are siblings with indices $j$ and $\ell$ respectively, we use the estimate on $a_{n-1}(p) + a_{n-1}(y) \lesssim_{M, \eta} N (\sin \theta_j + \sin \theta_\ell)$ and obtain
	\begin{align*}
		\frac{\rho_p + \rho_y}{  \left \lvert {p-y}  \right \rvert     } \lesssim_{M, \eta} \frac{ N  (\sin \theta_j + \sin \theta_\ell ) r^{n-1} }{  \left \lvert {Q_q(q_j) - Q_q(q_\ell)}  \right \rvert     r^{n-2} } \lesssim_{M, \eta} \frac{N r (\sin \theta_j + \sin \theta_\ell ) }{  \left \lvert {q_j-q_\ell}  \right \rvert     } \lesssim_{M, \eta} \tau,
	\end{align*}
	where the last inequality follows from \eqref{eqTX23} in Lemma \ref{lem:cheb}. If instead $y \in \mathcal{Y}_\ell(p)$ for some $\ell \ge 2$, then for $N$ large enough depending on $M$ and $\eta$, we conclude using Lemma \ref{lem:ahlf_reg} that 
	\begin{align*}
		\frac{  \rho_p + \rho_y  }{  \left \lvert {p-y}  \right \rvert     } \lesssim_{M, \eta} \frac{  N r^{n-1}  }{ N^{-2}  r^{n-1-\ell} } \lesssim_{M, \eta} N^3 r^2 = (N r) \tau \ll \tau,
	\end{align*}
	for $N$ large. This completes the proof of the first claim.

	As for the second claim, suppose again that $p$ has index $j$ and $\hat{p} = q \in K_{n-2}$. We split the sum in \eqref{eq:geometric-sum} by $y \in \mathcal{Y}_\ell(p)$ for $1 \le \ell \le n-1$. The set of  $y \in \mathcal{Y}_1(p)$ are indexed by $y_i=q+\rho_qQ_q(q_i)$ for $i \ne j$, and for such $y_i$ we have that 
	\begin{align*}
		 \left \lvert {p - y_i}  \right \rvert    = \rho_q  \left \lvert { Q_q(q_j) - Q_q(q_i)}  \right \rvert    \simeq \rho_q  \left \lvert {q_i - q_j}  \right \rvert   ,
	\end{align*}
	since for $\tau$ small, $Q_q$ is bi-Lipschitz. In particular, we see that 
	\begin{align*}
		\sum_{y \in \mathcal{Y}_1(p)} \frac{ \rho_p^{d-a} \rho_y^{a}  }{ \left \lvert {p -y }  \right \rvert   ^d} \lesssim_{d, M, \eta} (Nr)^d \sin^{d-a} \theta_j \sum_{i \ne j} \frac{ \sin^a \theta_i }{  \left \lvert {q_j - q_i}  \right \rvert   ^d } \lesssim_{d, M, \eta} (N r)^d N^d \lesssim_{d, M, \eta} \tau^d 
	\end{align*}
	by virtue of Lemma \ref{lem:weighted}.

	On the other hand, for $y \in \mathcal{Y}_\ell(p)$ for $\ell \ge 2$ we apply Lemma \ref{lem:ahlf_reg} for $N$ large to see that $ \left \lvert {y-p}  \right \rvert    \gtrsim_{M, \eta}  N^{-2} r^{n-1-\ell}$, and since $\# \mathcal{Y}_\ell(p) \le N^\ell$, we have 
	\begin{align*}
		\sum_{\ell = 2}^{n-1} \sum_{y \in \mathcal{Y}_\ell(p)} \frac{ \rho_p^{d-a} \rho_y^a  }{  \left \lvert {p-y}  \right \rvert   ^d } \lesssim_{d, M, \eta} N^{3d} \sum_{\ell =2}^{n-1} (N r^d )^\ell   \lesssim_{d, M, \eta} N^{3d + 2} r^{2d} = N^{-d+2} \tau^{2d} \le \tau^d,
	\end{align*}
	since $d \ge 2$ and $\tau \in (0,1)$ for $N$ sufficiently large. This completes the proof.

\label{lem:field-local}
For $N$ sufficiently large, the following estimates hold for every
$1\le d\le M$ and $n\ge1$:
\begin{equation}
\label{eq:sibling-field-new}
N\rho_p^d|S_{n,d}(p)|
\lesssim_{M,\eta}
N\tau^d.
\end{equation}
If $n\ge2$, then
\begin{equation}
\label{eq:field-transmission-normalized}
\frac{
N\rho_p^d\,N|F_{n-1,d}(q)|
}{
N\tau^d
}
\lesssim_{M,\eta}
\tau X_{n-1,d}.
\end{equation}

\label{lem:field-evaluation}
Fix $1\le d\le M$ and $n\ge2$, and write
\[
    p=q+h.
\]
Then
\begin{equation}
\label{eq:Eev-expansion-new}
E_{n,d}^{\mathrm{ev}}(p)
=
N\sum_{t=1}^{M-d}
c_{d,t}h^tF_{n-1,d+t}(q)
+
\mathcal R_{n,d}^{\mathrm{ev}}(p),
\end{equation}
where
\[
c_{d,t}
=
(-1)^t\binom{d+t-1}{t},
\]
with the convention that the sum is empty when $d=M$.

Moreover, for $1\le t\le M-d$,
\begin{equation}
\label{eq:Eev-explicit-new}
\frac{
N\rho_p^d
\left|Nh^tF_{n-1,d+t}(q)\right|
}{
N\tau^d
}
\lesssim_{M,\eta}
\tau^{t+1}X_{n-1,d+t},
\end{equation}
and
\begin{equation}
\label{eq:Eev-rem-new}
\frac{
N\rho_p^d
|\mathcal R_{n,d}^{\mathrm{ev}}(p)|
}{
N\tau^d
}
\lesssim_{M,\eta}
\tau^{M+1}.
\end{equation}

If $p$ is the $j$-th child of $q$, then
\[
    h=\rho_qQ_q(q_j),
\]
and hence $|h|\lesssim_M\rho_q$.  For
$z\in K_{n-1}\setminus\{q\}$, Lemma~\ref{lem:prev_estimates} gives
\[
    \frac{|h|}{|q-z|}
    \lesssim_{M,\eta}
    \frac{\rho_q}{|q-z|}
    \lesssim_{M,\eta}\tau.
\]
After taking $\tau$ sufficiently small, this ratio is at most $1/2$.
Thus the Taylor expansion below is uniform in $z$.

Taylor's formula gives
\[
(p-z)^{-d}
=
\sum_{t=0}^{M-d}
c_{d,t}
\frac{h^t}{(q-z)^{d+t}}
+
O_M\left(
\frac{|h|^{M-d+1}}{|q-z|^{M+1}}
\right).
\]
Subtracting the term with $t=0$ and summing over $z\ne q$ gives
\eqref{eq:Eev-expansion-new}.

For an explicit term,
\[
N\rho_p^d
\left|Nh^tF_{n-1,d+t}(q)\right|
=
N
\left(\frac{\rho_p}{\rho_q}\right)^d
\left(\frac{|h|}{\rho_q}\right)^t
|\Lambda_{n-1,d+t}(q)|.
\]
Since
\[
    |h|\lesssim_M\rho_q,
    \qquad
    \frac{\rho_p}{\rho_q}
    \lesssim_{M,\eta}\frac{\tau}{N},
\]
the definition of $X_{n-1,d+t}$ yields
\begin{align*}
\frac{
N\rho_p^d
\left|Nh^tF_{n-1,d+t}(q)\right|
}{
N\tau^d
}
&\lesssim_{M,\eta}
N^{1-d}\tau^{d+t}X_{n-1,d+t}\\
&\le
C_{M,\eta}\tau^{t+1}X_{n-1,d+t}.
\end{align*}
This proves \eqref{eq:Eev-explicit-new}.

For the remainder,
\begin{align*}
N\rho_p^d
|\mathcal R_{n,d}^{\mathrm{ev}}(p)|
&\lesssim_M
N^2\rho_p^d
|h|^{M-d+1}
\sum_{\substack{z\in K_{n-1}\\z\ne q}}
\frac1{|q-z|^{M+1}}\\
&\lesssim_{M,\eta}
N^2
\left(\frac{\rho_p}{\rho_q}\right)^d
\rho_q^{M+1}
\sum_{\substack{z\in K_{n-1}\\z\ne q}}
\frac1{|q-z|^{M+1}}.
\end{align*}
Applying Lemma~\ref{lem:prev_estimates} to $q$ with exponent
$M+1$ and $a=0$,
\[
\rho_q^{M+1}
\sum_{\substack{z\in K_{n-1}\\z\ne q}}
\frac1{|q-z|^{M+1}}
\lesssim_{M,\eta}
\tau^{M+1}.
\]
Hence
\[
N\rho_p^d
|\mathcal R_{n,d}^{\mathrm{ev}}(p)|
\lesssim_{M,\eta}
N^{2-d}\tau^{d+M+1}.
\]
After division by $N\tau^d$,
\[
\frac{
N\rho_p^d
|\mathcal R_{n,d}^{\mathrm{ev}}(p)|
}{
N\tau^d
}
\lesssim_{M,\eta}
N^{1-d}\tau^{M+1}
\le
C_{M,\eta}\tau^{M+1}.
\]

\label{lem:field-cluster}
For $1\le d\le M$ and $n\ge2$,
\begin{equation}
\label{eq:Ecl-field-new}
N\rho_p^d
|E_{n,d}^{\mathrm{cl}}(p)|
\lesssim_{M,\eta}
N\tau^{d+2}.
\end{equation}
Equivalently,
\begin{equation}
\label{eq:Ecl-field-normalized}
\frac{
N\rho_p^d
|E_{n,d}^{\mathrm{cl}}(p)|
}{
N\tau^d
}
\lesssim_{M,\eta}
\tau^2.
\end{equation}

\label{lem:polynomial-renormalization}
	Fix $M\ge2$, $\eta >0$, and assume that the sets $K_0, \dotsc K_{n-1}$ have been constructed so as to satisfy the assumptions \eqref{eq:old-children}-\eqref{eq:old-scale-bound} and additionally, that 
	\begin{equation}
		\label{eq:field-hypothesis-renormalization}
		|\Lambda_{n-1,d}(p)|
		\lesssim_M
		N\tau^d,
		\qquad
		1\le d\le M,
	\end{equation}
	holds uniformly for $p\in K_{n-1}$.

	Then if $N$ is sufficiently large, depending on $M$, $s$, and $\eta$,  there exists a choice of polynomials
	\begin{align}
		P_{m+1,p}, \qquad p \in K_{n-1},  \; \; 1 \le m \le M-1
	\end{align}
	for which \eqref{eq:new-correction-bounds} and
	\eqref{eq:new-correction-normalization} hold, and for which each $x = x_k = p + \rho_p Q_p(q_k) \in K_n$ satisfies
	\begin{equation}
		\label{eq:renormalized-error}
		\Delta_1(k)+\Delta_2(k)+\Delta_3(k)
		=
		(N-1)\log\rho_p+b_*+\beta_k+E_{M,p}(q_k),
	\end{equation}
	where
	\begin{equation}
		\label{eq:renormalized-error-bound}
		|E_{M,p}(q_k)|
		\lesssim_{M, \eta }
		N\tau^M.
	\end{equation}	
	Moreover,
	\begin{equation}
		\label{eq:renormalized-Q-derivative}
		\|Q_p-\mathrm{Id}\|_{C^1([-1,1])}
		\lesssim_M\tau,
	\end{equation}
	and
	\begin{equation}
		\label{eq:renormalized-barycenter}
		\sum_{k=1}^NQ_p(q_k)=0.
	\end{equation}

The proof proceeds by induction on $1 \le m \le M-1$, as follows. For $m=1$ (which corresponds to choosing a single quadratic $P_{2,p}$), we observe that Lemma \ref{lem:higher-basic-error} (with each $Q_p \equiv \mathrm{Id})$ gives us that 
	\begin{align*}
		\Delta_1(k) + \Delta_2(k) + \Delta_3(k) = (N-1) \log \rho_p + b_* + \beta_k + R_{1,p}(q_k) + E_{2,p}(q_k)
	\end{align*}
	with $\| R_{1,p} \|_{\mathrm{coeff}} \lesssim_{M} N \tau = N^3 r$, and $ \left \lvert {E_{2,p}}  \right \rvert    \lesssim_{M, \eta } N \tau^2 = N^5 r^2$. The reader should compare this estimate with Lemma \ref{lem:basic-error}; the additional information we have gained, is that the low order error in $N^3 r$ is a polynomial in $q_k$. By Lemma \ref{lem:L_prop}, we may choose a polynomial $P_{2,p}$ of degree at most $2$ for which 
	\begin{align*}
		\sum_{k=1}^N P_{2,p}(q_k) = 0, \; \; \; LP_{2,p} = -R_{1,p},  \; \; \; \text{ and }  \| P_{2,p} \|_{C^1([-1,1])} \lesssim_M N^{-1} \| R_{1,p} \|_{\mathrm{coeff}} \lesssim_M \tau.
	\end{align*}
	Notice that we may guarantee the first cancellation condition above, since $L(\mathrm{const}) = 0$. Once again applying Lemma \ref{lem:higher-basic-error}, but now with $Q_p(t) = t + P_{2,p}(t)$, (which indeed satisfies \eqref{eq:new-correction-bounds} and \eqref{eq:new-correction-normalization}, by the above), we then obtain the new errors
	\begin{align*}
		\Delta_1(k) & + \Delta_2(k) + \Delta_3(k) \\
		& = (N-1) \log \rho_p + b_* + \beta_k + L P_{2,p}(q_k) + R_{1,p}(q_k)   + E_{2,p}(q_k) \\
		& = (N-1) \log \rho_p + b_* +\beta_k  +  E_{2,p}(q_k),
	\end{align*}
	by the choice of $P_{2,p}$, and from the fact that $R_{1,p}$ is a linear polynomial which is independent of $P_{2,p}$. Moreover, that same Lemma yields the bounds $  \left \lvert {E_{2,p}(q_k)}  \right \rvert    \lesssim_{M, \eta} N \tau^2$. This is exactly the desired base case for $m = 1$. 

	Assume now that for some $1 \le m \le M-2$, we have chosen the polynomials $P_{2,p}, \dotsc, P_{m+1, p}$ in such a way that for each $1 \le j \le m$, 
	\begin{align}\label{eq:desired_bds}
		\sum_{k=1}^{N} P_{j+1, p}(q_k) = 0, \; \; \; L P_{j+1,p} = - R_{j,p}, \; \; \; \text{ and } \| P_{j+1,p}  \|_{C^1([-1,1])} \lesssim_M \tau^j.
	\end{align}
	Here, $R_{1,p} \in \mathcal{P}_1$ is as in the base case, and for $j \ge 2$, $R_{j,p} \in \mathcal{P}_{j}$ is the remainder polynomial given by Lemma \ref{lem:higher-basic-error} with the deformation $Q_p(t) = t + P_{2,p}(t) + \cdots +  P_{j, p}(t)$. 
	Since each $R_{j,p}$ depends \textit{just} on the polynomials $P_{\ell, y}$ for $y \in K_{n-1}$ and $1 \le \ell \le j$, we have that $R_{j, p} \in \mathcal{P}_{j}$ is also the same remainder polynomial as in Lemma \ref{lem:higher-basic-error} for the deformation $Q_p(t) = t + P_{2,p}(t) + \cdots + P_{m+1,p} (t) + P_{m+2, p}(t)$ whenever $P_{m+2,p}(t)$ has degree at most $m+2$ and satisfies $\| P_{m+2,p} \|_{C^1([-1,1])} \lesssim_M \tau^{m+1}$. In particular, if we apply Lemma \ref{lem:higher-basic-error} for this deformation, we obtain the error	 
	\begin{align*}
		\Delta_1(k) & + \Delta_2(k) + \Delta_3(k) \\
		& = (N-1) \log \rho_p + b_* + \beta_k + \sum_{j=1}^{m+1} \left( LP_{j+1,p}(q_k) + R_{j,p}(q_k) \right) + E_{m+2, p}(q_k) \\
		& = (N-1) \log \rho_p + b_* + \beta_k + LP_{m+2,p}(q_k) + R_{m+1, p}(q_k)   +  E_{m+2, p}(q_k),
	\end{align*}	
	since the sum over $1 \le j \le m$ cancels exactly. Using Lemma \ref{lem:L_prop}, we then choose for each $p \in K_{n-1}$ some polynomial $P_{m+2, p} \in \mathcal{P}_{m+2}$ satisfying
$$
		\sum_{k=1}^N P_{m+2,p}(q_k) = 0, \qquad LP_{m+2,p} = -R_{m+1,p},$$
and		
		   $$ \| P_{m+2,p} \|_{C^1([-1,1])} \lesssim_M N^{-1} \| R_{m+1,p} \|_{\mathrm{coeff}} \lesssim_M \tau^{m+1},
$$
	where the last inequality is a consequence of Lemma \ref{lem:higher-basic-error}. This proves the induction claim on the choice of the polynomials $P_{j+1, p}$. Moreover, from the above inequality, we deduce also that with the choice of deformation $Q_p(t) = t + P_{2,p}(t) + \cdots + P_{m+2,p}(t)$, the error satisfies
	\begin{align*}
		\Delta_1(k) + \Delta_2(k) + \Delta_3(k) = (N-1) \log \rho_p + b_* + \beta_k + E_{m+2,p}(q_k),
	\end{align*}
	which for $m+1 = M-1$, is the desired conclusion of our Lemma. What is left to check are \eqref{eq:renormalized-Q-derivative} and \eqref{eq:renormalized-barycenter}, but these are clear for $N$ large by our choice of the polynomials $P_{j+1, p}$ and the bounds \eqref{eq:desired_bds}.

\label{lem:finite-order-induction}
Fix $s \in (0,1/2)$, and $\eta>0$ small. Then for $N$ large enough, depending on $s$ and $\eta$, one can construct the sets $K_0, K_1, \dotsc, K_n$ of the form $K_0 = \{0\}$, 
\begin{align*}
	K_{n} = \bigcup_{p \in K_{n-1}} \left \{ x = p + a_{n-1}(p) r^{n-1} Q_p(q_k) \; : \; 1 \le k \le N    \right \} ,
\end{align*}
so that for each $n \ge 1$ and $ x \in K_n$, we have 
\begin{align}\label{eq:general-invariant-new}
	g_n(x) & \coloneqq  N^{-n} \sum_{\substack{ y \in K_n \\ y \ne x   }} \log \left \lvert {x-y}  \right \rvert    =  c_n + N^{-n} \left( \beta_{j(x)} + e_n(x)  \right), \qquad  \left \lvert {e_n(x)}  \right \rvert    \le \eta,
\end{align}
where $c_n \in {\mathbb R}$ converges as $n \rightarrow \infty$. Moreover, for every $n \ge 2$ and $p \in K_{n-1}$, we have 
\[
	1 \le a_{n-1}(p) \lesssim_\eta N \sin \theta_{j(p)}
\]
and additionally, the $Q_p$ satisfy 
\begin{align*}
	\| Q_p - \mathrm{Id}   \|_{ C^{1}([-1,1]) } \lesssim_{s, \eta} N^2 r \ll 1,  \; \;\; \;  \sum_{k=1}^N Q_p(q_k) = 0.  
\end{align*}

\label{thm:main-general-new}
	For every $0 < s< 1/2$, there exists an $s$-Ahlfors regular compact set $K \subset {\mathbb R} \subset {\mathbb C}$ so that the harmonic measure in ${\mathbb C} \setminus K$ with pole at infinity $\omega^\infty$ is equivalent to $\mathcal{H}^s|_K$, i.e., there is some $C \ge 1$ so that 
	\begin{align*}
		 C^{-1} \, \mathcal{H}^s|_K(F)\le \omega^\infty(F) \le C \mathcal{H}^s|_K(F) \text{ for all } F \subset K \text{ Borel.}
	\end{align*}
	In particular, $\dim \omega^\infty = s$.
